          div(class = "download-row", downloadButton("download_project", "Save project JSON")),
          fileInput("project_file", "Open a LabStats project", accept = ".json"), p(class = "hint", "The project contains all tables, saved analysis snapshots, graph settings, layouts and notes. Opening a project recalculates its saved analyses in R."))),
        tabPanel("Export & R code", value = "export", div(class = "tab-body", h3("Reproduce this analysis"),
